import "@shopify/shopify-app-react-router/adapters/node";
import {
  ApiVersion,
  AppDistribution,
  shopifyApp,
} from "@shopify/shopify-app-react-router/server";
import { PostgreSQLSessionStorage } from "@shopify/shopify-app-session-storage-postgresql";

/**
 * Authentication handled by Shopify (session tokens, token exchange) through
 * the official template: no external auth service, nothing to pay for.
 *
 * The template generated by `shopify app init` stores sessions with Prisma;
 * here we keep a single Postgres for the whole project.
 */
const sessionStorage = new PostgreSQLSessionStorage(
  new URL(requiredEnv("DATABASE_URL")),
);

const shopify = shopifyApp({
  apiKey: process.env.SHOPIFY_API_KEY ?? "",
  apiSecretKey: requiredEnv("SHOPIFY_API_SECRET"),
  apiVersion: ApiVersion.January26,
  ...(process.env.SCOPES ? { scopes: process.env.SCOPES.split(",") } : {}),
  appUrl: requiredEnv("SHOPIFY_APP_URL"),
  authPathPrefix: "/auth",
  sessionStorage,
  distribution: AppDistribution.AppStore,
});

function requiredEnv(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`${name} is missing: check your .env`);
  return value;
}

export default shopify;
export const apiVersion = ApiVersion.January26;
export const addDocumentResponseHeaders = shopify.addDocumentResponseHeaders;
export const authenticate = shopify.authenticate;
export const unauthenticated = shopify.unauthenticated;
export const login = shopify.login;
export const registerWebhooks = shopify.registerWebhooks;
export const sessionStorageInstance = sessionStorage;
